      "id": "fdistribution-5aac64e97ffc",
      "command": "FDistribution",
      "signature": "FDistribution( <Numerator Degrees of Freedom>, <Denominator Degrees of Freedom>, <Variable Value> )",
      "parameterTypes": [
        "numerator degrees of freedom",
        "denominator degrees of freedom",
        "variable value"
      ],
      "parameterRoles": [
        "Numerator Degrees of Freedom",
        "Denominator Degrees of Freedom",
        "Variable Value"
      ],
      "arity": {
        "min": 3,
        "max": 3,
        "variadic": false
      },
      "outputKind": "unknown",
      "outputCardinality": "unknown",
