      "command": "Locus",
      "signature": "Locus( <Point Creating Locus Line Q>, <Point P>)",
      "parameterTypes": [
        "point creating locus line q",
        "point"
      ],
      "parameterRoles": [
        "Point Creating Locus Line Q",
        "Point P"
      ],
      "arity": {
        "min": 2,
        "max": 2,
        "variadic": false
      },
      "outputKind": "unknown",
      "outputCardinality": "unknown",
      "effect": "unknown",
      "dimension": "unknown",
      "safety": "unknown",
      "description": "Returns the locus curve of the point Q, which depends on the point P.",
      "usage": {
        "text": "Returns the locus curve of the point _Q_, which depends on the point _P_.\n\n[NOTE]\n====\n\nPoint _P_ needs to be a point on an object (e. g. line, segment, circle).\n\n====",
        "truncated": false
      },
