      "sourcePath": "en/modules/ROOT/pages/commands/Numeric.adoc",
      "sourceUrl": "https://geogebra.github.io/docs/manual/en/commands/Numeric/",
      "sourceCommit": "16454c25f339d10bcf99cfcbc5587b4ad19b24ba",
