      "id": "trig-expand-98ff55897e7f",
      "command": "TrigExpand",
      "signature": "TrigExpand( <Expression>, <Target Function>, <Target Variable>, <Target Variable> )",
      "parameterTypes": [
        "expression",
        "target function",
        "target variable",
        "target variable"
      ],
      "parameterRoles": [
        "Expression",
        "Target Function",
        "Target Variable",
        "Target Variable"
      ],
      "arity": {
        "min": 4,
        "max": 4,
        "variadic": false
      },
      "outputKind": "unknown",
      "outputCardinality": "unknown",
